// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address actor, address newOwner) public {
        // wide domain: any caller, any target; exclude only the caller being the current owner's
        // own test-deployer? no — the current owner IS this test contract, keep it reachable too.
        vm.assume(newOwner != address(0)); // zero target is independently rejected in both versions

        address ownerBefore = c.owner();

        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: ownership changed iff the caller was the current owner,
        // and then it changed exactly to newOwner; any other caller left it untouched.
        assertTrue(
            ok ? (actor == ownerBefore && c.owner() == newOwner) : (c.owner() == ownerBefore),
            "ownership may only change when the current owner calls transferOwnership"
        );
    }
}
